2. npm ci --ignore-scripts && npx playwright install chromium
3. In vitest.e2e.config.ts change include to ['usr/**/*.e2e.ts', 'apps/studio/e2e/**/*.e2e.ts'] (local edit, only so Vitest picks up the script).
4. Save the script below as usr/real.e2e.ts.
5. npx vitest run --config vitest.e2e.config.ts usr/real.e2e.ts (needs the internet)
6. Read usr/real-out.txt.

--- usr/real.e2e.ts ---
import { writeFileSync } from 'node:fs';
import { chromium } from 'playwright';
import { it } from 'vitest';
import * as checks from '@refraction/kit/src/page-checks/index.js';
const C = checks as unknown as Record<string, unknown>;
const URLS = ['https://example.com/', 'https://en.wikipedia.org/wiki/Bread', 'https://www.gov.uk/', 'https://www.w3.org/WAI/', 'https://news.ycombinator.com/', 'https://developer.mozilla.org/en-US/docs/Web/HTML/Element/dialog'];
it('real', async () => {
  const browser = await chromium.launch();
  const out: string[] = [];
  for (const url of URLS) {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1280, height: 800 });
    try { await page.goto(url, { waitUntil: 'load', timeout: 30000 }); } catch (e) { out.push(`${url} :: GOTO ${String(e).slice(0, 120)}`); await page.close(); continue; }
    await page.waitForTimeout(1000);
    for (const fn of Object.keys(C)) {
      if (fn === 'noScriptedMotion') continue;
      if (fn === 'noSidewaysScroll') await page.setViewportSize({ width: 320, height: 800 });
      let res: unknown; const t = Date.now();
      try { res = await page.evaluate(`(${String(C[fn])})(document${fn === 'tokenFit' ? ', {}' : ''})`); } catch (e) { res = 'THREW ' + String(e).slice(0, 200); }
      if (fn === 'noSidewaysScroll') await page.setViewportSize({ width: 1280, height: 800 });
      const list = Array.isArray(res) ? res as { ruleId: string; status: string; where?: string; measured?: string }[] : [];
      const by: Record<string, number> = {};
      for (const f of list) by[`${f.ruleId}=${f.status}`] = (by[`${f.ruleId}=${f.status}`] ?? 0) + 1;
      const firsts = list.filter((f) => f.status === 'fails' || f.status === 'could-not-measure').slice(0, 3).map((f) => `${f.ruleId} @ ${String(f.where).slice(0, 70)} : ${String(f.measured).slice(0, 110)}`);
      out.push(`${url} :: ${fn} (${Date.now() - t} ms) :: ${Array.isArray(res) ? JSON.stringify(by) : String(res)}${firsts.length ? '\n      ' + firsts.join('\n      ') : ''}`);
    }
    await page.close();
  }
  await browser.close();
  writeFileSync('usr/real-out.txt', out.join('\n') + '\n');
}, 600000);

