// Removal run: for every page-check record, remove the element(s) planted for it from flawed.html and see whether the rule still fails.
import { chromium } from 'playwright';
import { pathToFileURL } from 'node:url';
import { createServer } from 'vite';
const vite = await createServer({ server: { middlewareMode: true }, appType: 'custom', logLevel: 'silent' });
const kit = await vite.ssrLoadModule('/packages/kit/src/index.ts');
const checks = await vite.ssrLoadModule('/packages/kit/src/page-checks/index.ts');
const TOKENS = { '--ink': '#1a1a1a', '--paper': '#ffffff', '--accent': '#0b5fff', '--line': '#d0d5dd', '--radius': '8px', '--radius-in': '4px', '--font-body': 'serif' };
const browser = await chromium.launch({ executablePath: process.env.PW_CHROMIUM });
const url = pathToFileURL('packages/kit/fixtures/flawed.html').href;
async function fails(ruleId, fns, remove) {
  const width = ruleId === 'neuro-reflow' ? 320 : 1280;
  const ctx = await browser.newContext({ viewport: { width, height: 800 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  await page.goto(url, { waitUntil: 'load' });
  let planted = await page.evaluate((id) => document.querySelectorAll(`[data-defect~="${id}"]`).length, ruleId);
  if (remove) await page.evaluate((id) => document.querySelectorAll(`[data-defect~="${id}"]`).forEach((e) => e.remove()), ruleId);
  await page.waitForTimeout(400);
  const out = [];
  for (const fn of fns) { const f = await page.evaluate(`(${String(checks[fn])})(document${fn === 'tokenFit' ? `, ${JSON.stringify(TOKENS)}` : ''})`); out.push(...f.filter((x) => x.ruleId === ruleId && x.status === 'fails').map((x) => x.where)); }
  await ctx.close();
  return { planted, where: out };
}
for (const rule of kit.KIT_RULES.filter((r) => r.check.kind === 'page-check')) {
  const fns = [rule.check.fn, ...(rule.check.also ?? [])];
  const before = await fails(rule.id, fns, false);
  const after = await fails(rule.id, fns, true);
  console.log(`${rule.id}\tplanted=${before.planted}\tbefore=${before.where.length}\tafterRemoval=${after.where.length}\t${after.where.length ? 'STILL FAILS at ' + JSON.stringify(after.where.slice(0, 3)) : 'silent'}`);
}
await browser.close(); await vite.close();

