import { chromium } from 'playwright';
import { it } from 'vitest';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import * as checks from '../../../packages/kit/src/page-checks/index.js';
it('sec', async () => {
  const CHECKS = checks as unknown as Record<string, unknown>;
  const browser = await chromium.launch(process.env.PW_CHROMIUM ? { executablePath: process.env.PW_CHROMIUM } : {});
  const context = await browser.newContext({ viewport: { width: Number(process.env.SEC_WIDTH ?? 1280), height: 800 }, deviceScaleFactor: 1, javaScriptEnabled: process.env.SEC_JS !== '0' });
  const page = await context.newPage();
  const lines: string[] = [];
  page.on('request', (r) => { if (!r.url().startsWith('file:')) lines.push('NETWORK ' + r.url()); });
  await page.goto(pathToFileURL(resolve('sec-page.html')).href, { waitUntil: 'load' });
  await page.waitForTimeout(300);
  const tokens = existsSync('sec-tokens.json') ? readFileSync('sec-tokens.json', 'utf8') : JSON.stringify({ '--ink': '#1a1a1a', '--paper': '#ffffff', '--accent': '#0b5fff', '--line': '#d0d5dd', '--radius': '8px', '--radius-in': '4px', '--font-body': 'serif' });
  for (const fn of (process.env.SEC_CHECKS ?? '').split(',')) {
    const t = Date.now();
    let out: string;
    try {
      const r = await Promise.race([
        page.evaluate(`(${String(CHECKS[fn])})(document${fn === 'tokenFit' ? `, ${tokens}` : ''})`) as Promise<{ ruleId: string; status: string; where?: string; measured?: string }[]>,
        new Promise<never>((_, no) => setTimeout(() => no(new Error('NO ANSWER AFTER 30 s')), 30000)),
      ]);
      out = r.length === 0 ? '(no finding)' : r.slice(0, 6).map((f) => `${f.ruleId}: ${f.status}${f.where ? ' @' + f.where.slice(0, 60) : ''}${f.measured ? ' [' + f.measured.slice(0, 110) + ']' : ''}`).join(' | ') + (r.length > 6 ? ` | ... ${r.length} findings in all` : '');
    } catch (e) { out = 'THROWS ' + String(e).split('\n')[0]; }
    lines.push(`${fn}${Date.now() - t >= 5000 ? ` (${Math.round((Date.now() - t) / 1000)} s)` : ''}: ${out}`);
  }
  writeFileSync('sec-out.txt', lines.join('\n') + '\n');
  await Promise.race([browser.close(), new Promise((ok) => setTimeout(ok, 5000))]);
}, 600000);

