    businessName: 'Acme Plumbing & Heating',
    whatItDoes: 'We repair boilers, fix leaks and fit bathrooms in homes across Leeds.',
    audience: 'Homeowners and landlords in Leeds',
    mainJob: 'Call us for a free quote',
    headline: 'Your boiler fixed today, or the call-out is free',
    services: [
      { name: 'Boiler repair', description: 'Same-day repair of gas boilers by Gas Safe engineers.' },
      { name: 'Bathroom fitting', description: 'We design and fit bathrooms, from one tap to a full refit.' },
