    proof: [{ text: 'They came within the hour and the price was exactly as quoted.', from: 'Jo' }],
    voice: { tone: 'friendly', length: 'brief', stance: 'confident' },
    wordsToAvoid: ['cheap'],
  };
  tryIt('brief-sound-acme', () => checkBrief(sound));
