  const filler = {
    businessName: 'Business Name', whatItDoes: 'We provide quality services to our valued customers.', audience: 'Everyone', mainJob: 'Click here', headline: 'Headline goes here',
    services: [{ name: 'Service One', description: 'Description of service one.' }, { name: 'Service Two', description: 'Description of service two.' }, { name: 'Service Three', description: 'Description of service three.' }],
    contact: { phone: '12345', email: 'you@yourdomain.com', address: 'Address line 1' }, proof: [{ text: 'Testimonial text will appear in this space.', from: 'Customer Name' }],
    voice: { tone: 'friendly', length: 'brief', stance: 'modest' }, wordsToAvoid: [],
  };
  tryIt('brief-filler', () => checkBrief(filler));
  const gibberish = { ...filler, businessName: 'asdf', whatItDoes: 'asdf asdf asdf asdf', audience: 'xxxxx', mainJob: '.....', headline: 'aaaaa', services: [1, 2, 3].map(() => ({ name: 'xx', description: 'xxxxxxxxxx' })), contact: { phone: '.....' }, proof: [{ text: '..........' }] };
  tryIt('brief-gibberish', () => checkBrief(gibberish));
  const todo = { ...sound, businessName: 'Todo Para Mascotas', headline: 'Todo para tu perro y tu gato', whatItDoes: 'Vendemos todo lo que tu mascota necesita, en el centro de Sevilla.', wordsToAvoid: ['we'] };
  tryIt('brief-spanish-todo-and-avoid-we', () => checkBrief(todo));
  const dentist = { ...sound, businessName: 'Dr Li', whatItDoes: 'Family dentist.', audience: 'Families', mainJob: 'Book', headline: 'Smile', contact: { phone: '555-0142' }, proof: [{ text: '4.9 stars', from: 'Google' }], wordsToAvoid: ['a'] };
  tryIt('brief-short-honest', () => checkBrief(dentist));
  tryIt('brief-empty-string-fields', () => checkBrief({ ...sound, headline: '', wordsToAvoid: [''] }));
  // --- blind test
  const reviewers = ['Ann', 'Bob', 'Cy', 'Di', 'Ed'];
  const pages = ['t1', 't2', 't3', 't4', 't5', 't6', 'p1', 'p2', 'p3', 'p4', 'p5', 'p6'];
  const all = (judge: (r: number, p: string, i: number) => unknown, made: (p: string) => unknown) => reviewers.flatMap((reviewer, r) => pages.map((page, i) => ({ reviewer, page, madeBy: made(page), judgedPerson: judge(r, page, i) }))) as never;
  tryIt('blind-protocol-minimum-all-person', () => blindScore(all(() => true, (p) => (p[0] === 't' ? 'tool' : 'person'))).statement);
  tryIt('blind-protocol-minimum-coin', () => blindScore(all((r, p, i) => (r + i) % 2 === 0, (p) => (p[0] === 't' ? 'tool' : 'person'))));
  tryIt('blind-answers-as-words', () => blindScore(all((r, p) => (p[0] === 't' ? 'AI' : 'person'), (p) => (p[0] === 't' ? 'tool' : 'person'))).statement);
  tryIt('blind-madeBy-AI', () => blindScore(all(() => true, (p) => (p[0] === 't' ? 'AI' : 'person'))).statement);
  tryIt('blind-duplicate-rows', () => { const a = all(() => true, (p) => (p[0] === 't' ? 'tool' : 'person')) as unknown[]; return blindScore([...a.slice(0, 12), ...a.slice(0, 12), ...a.slice(0, 12), ...a.slice(0, 12), ...a.slice(0, 12)].map((x, i) => ({ ...(x as object), reviewer: 'Ann' + (i % 5 === 0 ? '' : ' '.repeat(i % 5)) })) as never).statement; });
  tryIt('blind-perfectly-told-apart', () => blindScore(all((r, p) => p[0] === 'p', (p) => (p[0] === 't' ? 'tool' : 'person'))).statement);
  // --- grade
  const floors = KIT_RULES.filter((r) => r.level === 'floor').map((r) => r.id);
  log('floors', floors);
  tryIt('grade-empty', () => grade([], KIT_RULES));
  tryIt('grade-all-na', () => grade(KIT_RULES.map((r) => ({ ruleId: r.id, status: 'not-applicable' })), KIT_RULES));
  tryIt('grade-fail-then-hold-same-floor', () => grade([{ ruleId: 'neuro-reflow', status: 'fails' }, { ruleId: 'neuro-reflow', status: 'holds' }], KIT_RULES));
  tryIt('grade-status-typo', () => grade([{ ruleId: 'neuro-reflow', status: 'failed' as never }], KIT_RULES));
  tryIt('grade-status-caps', () => grade([{ ruleId: 'neuro-reflow', status: 'Fails' as never }], KIT_RULES));
  tryIt('receipt-empty', () => receiptText(receipt([], KIT_RULES)));
  tryIt('receipt-one-fail', () => receiptText(receipt([{ ruleId: 'neuro-reflow', status: 'fails', where: 'table', measured: 'x', fix: 'y' }], KIT_RULES)));
  tryIt('repairPlan-empty-rounds', () => repairPlan([], KIT_RULES));
  tryIt('repairPlan-one', () => repairPlan([[{ ruleId: 'neuro-reflow', status: 'fails', where: 'table', measured: 'x', fix: 'y' }]], KIT_RULES));
  tryIt('designId-order', () => [designId({ '--a': '1px', '--b': '2px' }), designId({ '--b': '2px', '--a': '1px' }), designId({ '--a': '#FFF' }), designId({ '--a': '#fff' }), designId({ '--a': '#ffffff' }), designId({})]);
  tryIt('pixels', () => [comparePixels(new Uint8Array([0, 0, 0, 255]), new Uint8Array([0, 0, 0, 0])), comparePixels(new Uint8Array([]), new Uint8Array([]))]);
  tryIt('preferences', () => preferences([{ decision: 'corners', picked: 'round', rejected: 'square' }, { decision: 'corners', picked: 'square', rejected: 'round' }]));
  writeFileSync('usr/logic-out.txt', out.join('\n') + '\n');
});

