import { it } from 'vitest';
import { writeFileSync } from 'node:fs';
import { KIT_RULES, blindScore, checkBrief, grade, receipt, receiptText, repairPlan, designId, comparePixels, preferences } from '@refraction/kit';
it('logic', () => {
  const out: string[] = [];
  const log = (name: string, v: unknown): void => { out.push(`## ${name}\n${typeof v === 'string' ? v : JSON.stringify(v)}`); };
  const tryIt = (name: string, f: () => unknown): void => { try { log(name, f()); } catch (e) { log(name, 'THREW ' + String(e)); } };
  // --- Briefs
  const sound = {
    businessName: 'Acme Plumbing & Heating',
    whatItDoes: 'We repair boilers, fix leaks and fit bathrooms in homes across Leeds.',
    audience: 'Homeowners and landlords in Leeds',
    mainJob: 'Call us for a free quote',
    headline: 'Your boiler fixed today, or the call-out is free',
    services: [
      { name: 'Boiler repair', description: 'Same-day repair of gas boilers by Gas Safe engineers.' },
      { name: 'Bathroom fitting', description: 'We design and fit bathrooms, from one tap to a full refit.' },
      { name: 'Leak detection', description: 'We find hidden leaks with a thermal camera and fix them.' },
    ],
    contact: { phone: '0113 496 0000', email: 'hello@acmeplumbing.co.uk', address: '123 Main Street, Leeds LS1 4AB' },
    proof: [{ text: 'They came within the hour and the price was exactly as quoted.', from: 'Jo' }],
    voice: { tone: 'friendly', length: 'brief', stance: 'confident' },
    wordsToAvoid: ['cheap'],
  };
  tryIt('brief-sound-acme', () => checkBrief(sound));
  const two = { ...sound, businessName: 'Corner Bakery', contact: { phone: '01632 960123' }, services: sound.services.slice(0, 2), proof: [], wordsToAvoid: [] };
  tryIt('brief-two-services-no-proof', () => checkBrief(two));
  const filler = {
    businessName: 'Business Name', whatItDoes: 'We provide quality services to our valued customers.', audience: 'Everyone', mainJob: 'Click here', headline: 'Headline goes here',
    services: [{ name: 'Service One', description: 'Description of service one.' }, { name: 'Service Two', description: 'Description of service two.' }, { name: 'Service Three', description: 'Description of service three.' }],
    contact: { phone: '12345', email: 'you@yourdomain.com', address: 'Address line 1' }, proof: [{ text: 'Testimonial text will appear in this space.', from: 'Customer Name' }],
    voice: { tone: 'friendly', length: 'brief', stance: 'modest' }, wordsToAvoid: [],
  };
  tryIt('brief-filler', () => checkBrief(filler));
  const gibberish = { ...filler, businessName: 'asdf', whatItDoes: 'asdf asdf asdf asdf', audience: 'xxxxx', mainJob: '.....', headline: 'aaaaa', services: [1, 2, 3].map(() => ({ name: 'xx', description: 'xxxxxxxxxx' })), contact: { phone: '.....' }, proof: [{ text: '..........' }] };
  tryIt('brief-gibberish', () => checkBrief(gibberish));
